// Author: Soumyo Bhattacharjee
// Stage-3A capture-path smoke-test controller.
//
// This block deliberately drives the production rx_fifo_v3 write port from
// the real AFE frame-clock domain.  A persistent level generated by the
// configuration register is synchronized locally, then writes a
// deterministic lane-0 sample until rx_fifo_v3 reports completion.
// It does not start the FIFO reader or the QSPI stream transaction.
module tp_stage3_capture_smoke #(
    parameter int N_LANES       = 16,
    parameter int SAMPLE_WIDTH  = 20,
    parameter logic [SAMPLE_WIDTH-1:0] SAMPLE_DATA = 20'hA_53C9
) (
    input  logic                              frame_clk_i,
    input  logic                              rst_ni,
    input  logic                              enable_i,
    input  logic                              wr_done_i,

    output logic                              fifo_reset_o,
    output logic                              start_capture_o,
    output logic [N_LANES*SAMPLE_WIDTH-1:0]  fifo_data_o,
    output logic [N_LANES-1:0]               fifo_wr_en_o,

    output logic                              req_seen_o,
    output logic                              done_o,
    output logic [2:0]                        state_o,
    output logic [7:0]                        frame_gray_o,
    // Expose both stages of the enable synchronizer for hardware diagnosis.
    // These are state observations only; they do not feed the controller.
    output logic                              enable_meta_o,
    output logic                              enable_sync_o
);
    localparam logic [2:0] ST_IDLE   = 3'd0;
    localparam logic [2:0] ST_RESET  = 3'd1;
    localparam logic [2:0] ST_ARM    = 3'd2;
    localparam logic [2:0] ST_SETTLE = 3'd3;
    localparam logic [2:0] ST_WRITE  = 3'd4;
    localparam logic [2:0] ST_DONE   = 3'd5;

    logic [2:0] state_q;
    (* ASYNC_REG = "TRUE" *) logic enable_meta_q, enable_sync_q;
    logic [3:0] delay_q;
    logic [7:0] frame_count_q;

    always_comb begin
        fifo_reset_o    = (state_q == ST_RESET);
        start_capture_o = (state_q == ST_ARM);
        fifo_data_o     = '0;
        fifo_data_o[0 +: SAMPLE_WIDTH] = SAMPLE_DATA;
        fifo_wr_en_o    = '0;
        fifo_wr_en_o[0] = (state_q == ST_WRITE);
    end

    always_ff @(posedge frame_clk_i or negedge rst_ni) begin
        if (!rst_ni) begin
            enable_meta_q <= 1'b0;
            enable_sync_q <= 1'b0;
            state_q       <= ST_IDLE;
            delay_q       <= '0;
            req_seen_o    <= 1'b0;
            done_o        <= 1'b0;
            frame_count_q <= '0;
        end else begin
            enable_meta_q <= enable_i;
            enable_sync_q <= enable_meta_q;
            frame_count_q <= frame_count_q + 1'b1;

            unique case (state_q)
                ST_IDLE: begin
                    delay_q <= '0;
                    if (enable_sync_q) begin
                        req_seen_o <= 1'b1;
                        done_o     <= 1'b0;
                        state_q    <= ST_RESET;
                    end
                end
                ST_RESET: begin
                    if (delay_q == 4'd7) begin
                        delay_q <= '0;
                        state_q <= ST_ARM;
                    end else begin
                        delay_q <= delay_q + 1'b1;
                    end
                end
                ST_ARM: begin
                    if (delay_q == 4'd3) begin
                        delay_q <= '0;
                        state_q <= ST_SETTLE;
                    end else begin
                        delay_q <= delay_q + 1'b1;
                    end
                end
                ST_SETTLE: begin
                    if (delay_q == 4'd3) begin
                        delay_q <= '0;
                        state_q <= ST_WRITE;
                    end else begin
                        delay_q <= delay_q + 1'b1;
                    end
                end
                ST_WRITE: begin
                    if (wr_done_i) begin
                        done_o  <= 1'b1;
                        state_q <= ST_DONE;
                    end
                end
                ST_DONE: begin
                    // Re-arm only after firmware clears register-13 bit 28.
                    // The next asserted level is a new, lossless request.
                    if (!enable_sync_q) begin
                        req_seen_o <= 1'b0;
                        done_o     <= 1'b0;
                        state_q    <= ST_IDLE;
                    end
                end
                default: state_q <= ST_IDLE;
            endcase
        end
    end

    assign state_o      = state_q;
    assign frame_gray_o = frame_count_q ^ (frame_count_q >> 1);
    assign enable_meta_o = enable_meta_q;
    assign enable_sync_o = enable_sync_q;
endmodule
